    categories_history_origin_p2: "確かなのは、多くの国で何世代にもわたって親しまれてきた娯楽であること、そして印刷されたカテゴリーカードや文字用のサイコロが入った市販の箱入り版はずっと後に登場したことです。PaperGamesは紙とペンによる伝統的な形を守り、進行役の仕事だけを引き受けます。文字を引き、時間を計り、得点を合計します。",
